import random

def evaluate(current_reputation, observation, my_history, round_num):
    action = observation.get('action', 'cooperate')
    if action == 'cooperate':
        current_reputation = min(1.0, current_reputation + 0.35)
    else:
        current_reputation = max(-1.0, current_reputation - 0.35)
    current_reputation *= 0.95
    return current_reputation

def decide(recipient_reputation, round_num, my_history):
    threshold = 0.0
    base_prob = 0.8 if recipient_reputation > threshold else 0.2
    history_cooperate = sum(1 for h in my_history if h.get('action') == 'cooperate')
    total_actions = len(my_history)
    if total_actions > 0:
        history_ratio = history_cooperate / total_actions
        base_prob = base_prob + 0.1 * history_ratio
    return random.random() < (base_prob + 0.05 * min(1, round_num / 100))
